create table public.courses (
  id text not null,
  semester smallint not null,
  name text not null,
  emoji text not null,
  position integer default 0 not null,
  constraint courses_pkey PRIMARY KEY (id),
  constraint courses_semester_fkey FOREIGN KEY (semester) REFERENCES public.semesters(number),
  constraint courses_id_check CHECK ((id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text))
);

alter table public.courses enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.courses to service_role;
